<template><view v-if="modelValue" class="mask" @tap.self="$emit('update:modelValue',false)"><view class="sheet"><view class="head"><text>在线联系</text><text @tap="$emit('update:modelValue',false)">关闭</text></view><scroll-view scroll-y class="messages"><view v-for="m in messages" :key="m.id" class="message" :class="{mine:Number(m.senderMemberId)===memberId}">{{m.content}}</view></scroll-view><view class="send"><input v-model="content" maxlength="1000" placeholder="请输入消息"/><button size="mini" @tap="send">发送</button></view></view></view></template>
<script setup lang="ts">import{ref,watch}from'vue';import{rideApi}from'../../services/ride';const props=defineProps<{modelValue:boolean;rideId:number;memberId?:number}>();const emit=defineEmits(['update:modelValue']);const messages=ref<any[]>([]),content=ref('');async function load(){if(props.modelValue&&props.rideId)messages.value=await rideApi.messages(props.rideId)}async function send(){const text=content.value.trim();if(!text)return;await rideApi.sendMessage(props.rideId,text);content.value='';await load()}watch(()=>props.modelValue,load)</script>
<style scoped>.mask{position:fixed;z-index:100;inset:0;background:rgba(15,23,42,.35);display:flex;align-items:flex-end}.sheet{height:68vh;width:100%;background:#fff;border-radius:32rpx 32rpx 0 0;padding:24rpx;box-sizing:border-box}.head,.send{display:flex;align-items:center;justify-content:space-between}.head{font-weight:700}.messages{height:calc(68vh - 160rpx);padding:18rpx 0}.message{max-width:75%;margin:12rpx 0;padding:14rpx 18rpx;background:#e2e8f0;border-radius:18rpx}.message.mine{margin-left:auto;background:#bfdbfe}.send{gap:12rpx}.send input{flex:1;background:#f1f5f9;border-radius:30rpx;padding:14rpx 20rpx}</style>
